/// <summary>
/// Gets the <c>METCBCTInvoicePostingContract</c> object of the controller class.
/// </summary>
/// <returns>
/// An object of the <c>METCBCTInvoicePostingContract</c> class.
/// </returns>
public METCBCTInvoicePostingContract getChargethroughPostingContract()
{
    return this.getDataContractObject('_cbctInvoicePostingContract') as METCBCTInvoicePostingContract;
}

/// <summary>
/// Constructor method to create new instance of the class
/// </summary>
/// <returns>
/// An object of the <c>METCBCTInvoicePostingController</c> class.
/// </returns>
public static METCBCTInvoicePostingController construct()
{
    return new METCBCTInvoicePostingController(classstr(METCBCTInvoicePostingService),
                                                        methodstr(METCBCTInvoicePostingService, process),
                                                        SysOperationExecutionMode::Synchronous);
}

/// <summary>
/// Main method of the class 
/// </summary>
/// <param name="_args">
/// The instance of <c>Args</c> class.
/// </param>
public static void main(Args _args)
{
    METCBCTInvoicePostingController massTransferController = METCBCTInvoicePostingController::construct();
   
    massTransferController.parmDialogCaption("@MET:CBCTProcessChargeThroughInvoice");
    massTransferController.parmExecutionMode(SysOperationExecutionMode::Synchronous);
    massTransferController.startOperation();
    
}

/// <summary>
/// Is process retryable
/// </summary>
/// <returns>
/// If true is returned, the batch task is retryable, otherwise it is not.
/// </returns>
[Hookable(false)]
final boolean isRetryable()
{
    return true;
}

/// <summary>
/// Force the periodic to run in batch
/// </summary>
/// <returns>True</returns>
public boolean mustGoBatch()
{       
    return true;
}
